"""Build new versions of the three drafts with the corrected Gemma-27B labels. Reads the existing drafts, writes new files only:
  paper_2.0/numbers_v2.tex (corrected macros), paper_2.0/numbers_x2.tex (X2 and as-printed values, from CSVs and numbers.tex),
  paper_2.0/srw/main_v2.tex, paper_2.0/mere/main_v3.tex, paper_2.0/main_v2.tex, results/rejudge_gemma/paper_v2_changes.csv
Each wording change is an exact replacement that must occur exactly once in the old draft."""
import re
import sys
from pathlib import Path

import pandas as pd

REPO = Path(__file__).resolve().parents[1]
P, RJ = REPO / "paper_2.0", REPO / "results/rejudge_gemma"
old = {m[1]: m[2] for m in re.finditer(r"\\newcommand\{\\(\w+)\}\{(.*?)\}\s*% ", (P / "numbers.tex").read_text(encoding="utf-8"))}
(P / "numbers_v2.tex").write_text("% GENERATED (scripts/make_papers_v2.py) from results/rejudge_gemma/corrected: corrected Gemma-2-27B labels. numbers.tex is the as-printed version.\n"
                                  + (RJ / "corrected/paper_2.0__numbers.tex.new").read_text(encoding="utf-8"), encoding="utf-8")
C = pd.read_csv(REPO / "results/x2/coefficients.csv"); F = pd.read_csv(REPO / "results/x2/paper_sdpa_judge/coefficients.csv")
Q = pd.read_csv(REPO / "results/x2/questions.csv"); T1 = pd.read_csv(REPO / "results/x0_corrected/table1_corrected.csv").set_index("cell")
s = lambda v: f"{v:+.2f}".replace("+", "$+$").replace("-", "$-$")
ci = lambda r, k="obscurity": f"[{s(r[k + '_lo'])}, {s(r[k + '_hi'])}]"
row = lambda D, m, y: D[(D.model == m) & (D.outcome == y)].iloc[0]
M, src = {}, {}


def mac(n, v, f):
    M[n], src[n] = v, f


X = "results/x2/coefficients.csv"
for n, m in (("All", "two judges"), ("Mid", "deciles 2 to 9 only"), ("NoThree", "without country, capital and sport"), ("Levels", "knowledge score as 11 levels")):
    for t, y, mm in (("", "both", m), ("Regex", "regex24", "regex, 20 short replies" if n == "All" else m)):
        r = row(C, mm, y); mac(f"xt{n}{t}", s(r.b_obscurity), X); mac(f"xt{n}{t}CI", ci(r), X)
    mac(f"xt{n}N", f"{int(row(C, m, 'both').n):,}".replace(",", "{,}"), X)
p = row(C, "two judges", "both")
mac("xtKnow", s(p.b_knowledge), X); mac("xtKnowCI", ci(p, "knowledge"), X)
mac("xtPredPop", f"{p.predicted_at_popularity_90th:.2f}", X); mac("xtPredObs", f"{p.predicted_at_popularity_10th:.2f}", X)
mac("xtRel", str(int(p.relations)), X); mac("xtOld", s(row(F, "two judges", "both").b_obscurity), "results/x2/paper_sdpa_judge/coefficients.csv"); mac("xtOldCI", ci(row(F, "two judges", "both")), "results/x2/paper_sdpa_judge/coefficients.csv")
mac("cPopKnownAbs", f"{T1.abstention['popular known']:.3f}", "results/x0_corrected/table1_corrected.csv")
L = pd.read_csv(RJ / "labels_by_file.csv"); mac("cRejudged", f"{int(L.replies.sum()):,}".replace(",", "{,}"), "results/rejudge_gemma/labels_by_file.csv")
for n, m in (("Kappa", "hmLlamaKappa"), ("Margin", "hmLlamaDiff"), ("MarginCI", "hmLlamaDiffCI"), ("Unk", "rcUnk"), ("UnkCI", "rcUnkCI"), ("UnkJoint", "rcUnkJoint"), ("UnkJointCI", "rcUnkJointCI")):
    mac("asPrinted" + n, old[m], "paper_2.0/numbers.tex (as printed)")
(P / "numbers_x2.tex").write_text("% GENERATED by scripts/make_papers_v2.py\n" + "".join(f"\\newcommand{{\\{n}}}{{{v}}}  % {src[n]}\n" for n, v in M.items()), encoding="utf-8")

NOTE = (r"The labels of the Gemma-2-27B judge in an earlier version of this paper came from an incorrect forward pass: the default attention implementation of the transformers library (sdpa) omits the attention soft-capping that Gemma-2 uses. "
        r"We found this in a later experiment, after the results above had been seen, so the correction is post hoc. The stored labels are reproduced exactly with that implementation; with eager attention, and with vLLM, the labels agree with each other on all 1{,}161 Llama replies and differ from the stored ones. "
        r"We relabeled all \cRejudged{} stored replies with the same prompt and parser and kept the rule that both judges must say DONT\_KNOW. The two-judge agreement on Llama rose from $\kappa=\asPrintedKappa$ to \hmLlamaKappa{}, the %s from \asPrintedMargin{} \asPrintedMarginCI{} to \hmLlamaDiff{} \hmLlamaDiffCI, and the unknown-fact gap from \asPrintedUnk{} \asPrintedUnkCI{} to \rcUnk{} \rcUnkCI{} (after the label corrections, from \asPrintedUnkJoint{} \asPrintedUnkJointCI{} to \rcUnkJoint{} \rcUnkJointCI). "
        r"Agreement between two LLM judges is not validation against people. Gemma-2-9B as a tested model was run with the same implementation; on 300 questions its forced answers were equally correct and its entropies nearly identical ($r=0.999$) with the correct one. Its steering and lens runs were not rerun.")
ALL = []


def build(src_, dst, edits):
    t = (P / src_).read_text(encoding="utf-8")
    for a, b, why in edits:
        assert t.count(a) == 1, (src_, t.count(a), a[:90])
        t = t.replace(a, b)
        ALL.append(dict(draft=dst, reason=why, old=a, new=b))
    out = P / dst
    assert out.resolve() != (P / src_).resolve()
    out.write_text(t, encoding="utf-8")


num = lambda up: (rf"\input{{{up}numbers.tex}}", rf"\input{{{up}numbers_v2.tex}}" + "\n" + rf"\input{{{up}numbers_x2.tex}}", "corrected numbers")
fig = lambda f: (f"{f}.pdf", f"{f}_v2.pdf", "figure from corrected labels")
OLMO = r"for OLMo-2-7B the interval includes zero (\pmOlmoDiff{} \pmOlmoDiffCI)"
