# ---- static checks
known = set(re.findall(r"\\newcommand\{\\(\w+)\}", (P / "numbers_v2.tex").read_text() + (P / "numbers_x2.tex").read_text()))
for f in ("srw/main_v2.tex", "mere/main_v3.tex", "main_v2.tex"):
    t = (P / f).read_text(encoding="utf-8"); o = (P / f.replace("_v2", "").replace("main_v3", "main_v2")).read_text(encoding="utf-8")
    body = "\n".join(re.split(r"(?<!\\)%", l)[0] for l in t.splitlines())
    lab, ref = set(re.findall(r"\\label\{(.*?)\}", body)), {x for g in re.findall(r"\\[Cc]?(?:page)?ref\{(.*?)\}", body) for x in g.split(",")}
    used = set(re.findall(r"\\([A-Za-z]+)", body)); pref = {m for m in used if re.match(r"(tc|hm|tj|pm|xt|rc|ms|wr|sv|ga|nc|nq|fr|se|sd|eo|lk|lc|ek|am|hj|fa|gs|as[A-Z]|c[A-Z]|lo[A-Z]|cm[A-Z]|es[A-Z]|sc[A-Z]|mc[A-Z]|wl[A-Z]|jl[A-Z]|ec[A-Z]|ent[A-Z]|ff[A-Z])", m)}
    undefd = sorted(m for m in pref if m not in known and m not in set(re.findall(r"\\([A-Za-z]+)", o)))
    cites = set(re.findall(r"\\cite[pt]?\*?(?:\[.*?\])*\{(.*?)\}", body)); bib = (P / "references.bib").read_text(encoding="utf-8")
    missing = [c for g in cites for c in g.split(",") if c.strip() and f"{{{c.strip()}," not in bib]
    figs = [g for g in re.findall(r"\\includegraphics\[.*?\]\{(.*?)\}", body) if not any((b / g).exists() for b in ((P / f).parent, P / "figures"))]
    print(f, "| braces", body.count("{") - body.count("}"), "| $ even", len(re.findall(r"(?<!\\)\$", body)) % 2 == 0, "| env", sorted(re.findall(r"\\begin\{(\w+\*?)\}", body)) == sorted(re.findall(r"\\end\{(\w+\*?)\}", body)),
          "| refs undefined", sorted(ref - lab), "| macros undefined", undefd, "| cites missing", missing, "| figures missing", figs, "| words", len(o.split()), "->", len(t.split()))
